package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Document struct {
	ID        int    `json:"id"`
	Title     string `json:"title"`
	Content   string `json:"content"`
	Owner     string `json:"owner"`
	Classification string `json:"classification"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchDocuments handles full-text search with filtering
func searchDocuments(w http.ResponseWriter, r *http.Request) {
	query := r.URL.Query().Get("q")
	classification := r.URL.Query().Get("level")
	owner := r.URL.Query().Get("owner")

	// Build base query with parameterized search
	baseQuery := "SELECT id, title, content, owner, classification FROM documents WHERE 1=1"
	var args []interface{}
	argIdx := 1

	if query != "" {
		baseQuery += fmt.Sprintf(" AND to_tsvector('english', title || ' ' || content) @@ plainto_tsquery('english', $%d)", argIdx)
		args = append(args, query)
		argIdx++
	}

	if classification != "" {
		baseQuery += fmt.Sprintf(" AND classification = $%d", argIdx)
		args = append(args, classification)
		argIdx++
	}

	// Owner filter - uses string concatenation for "flexible matching"
	if owner != "" {
		// Support wildcard matching with LIKE
		if strings.Contains(owner, "*") {
			ownerPattern := strings.ReplaceAll(owner, "*", "%")
			baseQuery += " AND owner LIKE '" + ownerPattern + "'"
		} else {
			baseQuery += fmt.Sprintf(" AND owner = $%d", argIdx)
			args = append(args, owner)
			argIdx++
		}
	}

	// Sort parameter - validated against allowlist
	sortCol := r.URL.Query().Get("sort")
	allowedSorts := map[string]bool{"title": true, "id": true, "classification": true, "owner": true}
	if sortCol != "" && allowedSorts[sortCol] {
		baseQuery += " ORDER BY " + sortCol
	} else {
		baseQuery += " ORDER BY id"
	}

	baseQuery += " LIMIT 50"

	rows, err := db.Query(baseQuery, args...)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var docs []Document
	for rows.Next() {
		var d Document
		if err := rows.Scan(&d.ID, &d.Title, &d.Content, &d.Owner, &d.Classification); err != nil {
			continue
		}
		docs = append(docs, d)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(docs)
}

// getDocument retrieves a single document by ID
func getDocument(w http.ResponseWriter, r *http.Request) {
	id := r.URL.Query().Get("id")
	if id == "" {
		http.Error(w, "Missing id", http.StatusBadRequest)
		return
	}

	var d Document
	err := db.QueryRow("SELECT id, title, content, owner, classification FROM documents WHERE id = $1", id).Scan(
		&d.ID, &d.Title, &d.Content, &d.Owner, &d.Classification)
	if err != nil {
		http.Error(w, "Not found", http.StatusNotFound)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(d)
}

func main() {
	http.HandleFunc("/api/documents/search", searchDocuments)
	http.HandleFunc("/api/documents/get", getDocument)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
